_custom-inhealth.scss:
.cart-item-block {
    display: block;
    padding: 0;
    margin: 0;
}

.cart-item-info {
    width: 100%;

    + .cart-item-info {
        margin-top: 0;
    }
}



.cart-item-price {
    display: none;
}

.cart-item-totals {
    text-align: center;
    vertical-align: top;
    padding: $cart-item-spacing 0;

    @media (max-width: (screenSize("medium") - 1px)) {
        padding: 0;
        width: 100%;
        vertical-align: middle;

        .cart-item-info .cart-item-value {
            line-height: normal;
        }
    }
}

.cart-item-total {
    display: flex;
    align-items: end;
    justify-content: flex-end;
    flex-direction: column-reverse;
    font-size: fontSize("base");

    .cart-item-value {
        font-weight: fontWeight("bold");
    }

    .cart-item-value.price--discounted {
        font-weight: fontWeight("normal");
    }

    @media (max-width: (screenSize("medium") - 1px)) {
        justify-content: flex-end;
    }
}

.cart-item-quantity {
    display: flex;
    margin-right: spacing("half");
    max-width: max-content;
}
